// Walks the edge-lexer token tree and produces:
//   - a masked HTML source where every Edge construct is a stand-in;
//   - a side table mapping data-edge-id → Edge AST node.
//
// Block tags become <edge-block data-edge-id="N">…</edge-block> pairs with
// <edge-branch data-edge-id="N" data-branch-index="K" /> markers between
// branch bodies. Inline / void tags become
// <edge-self data-edge-id="N"></edge-self>. Expressions and comments become
// text tokens __EDGE_EXPR_N__ in any position; the splice phase looks at
// where each stand-in landed (text / attr value / attr name) to decide
// what kind of node to splice back.

import { BLOCK_TAGS, BRANCH_TAGS, INLINE_TAGS } from './taxonomy.js'

const MUSTACHE_KIND = {
  mustache: 'escaped',
  s__mustache: 'raw',
  e__mustache: 'literal',
  es__mustache: 'literal-raw',
}

const TAGARG_RE = /^__EDGE_TAGARG_(\d+)__$/

function restoreArgs(jsArg, tagArgs) {
  if (!tagArgs) return jsArg
  const m = TAGARG_RE.exec(jsArg.trim())
  if (!m) return jsArg
  const orig = tagArgs.get(Number(m[1]))
  return orig ?? jsArg
}

export function parseEdge(source, tokens, tagArgs) {
  const sideTable = new Map()
  let nextId = 0

  // Line cursor: tracks the source line we've "emitted up to". Used to
  // insert missing newlines that edge-lexer dropped (it discards the
  // newline separating a raw line from a following tag opener).
  let line = 1

  let out = ''

  function emitNewlinesTo(targetLine) {
    while (line < targetLine) {
      out += '\n'
      line += 1
    }
  }

  function classifyTag(tok) {
    const name = tok.properties.name
    const isVoid = tok.properties.selfclosed
    const head = name.split('.')[0]
    if (isVoid) return 'void'
    if (BLOCK_TAGS.has(head)) return 'block'
    if (BRANCH_TAGS.has(head)) return 'branch'
    if (INLINE_TAGS.has(head)) return 'inline'
    // Unknown @name(...) → component → block. Author would have written
    // `@!name(...)` to make it void; that case is caught by `isVoid` above.
    return 'block'
  }

  function emitMustache(tok) {
    emitNewlinesTo(tok.loc.start.line)
    const id = nextId++
    const kind = MUSTACHE_KIND[tok.type] ?? 'escaped'
    const inner = tok.properties.jsArg
    sideTable.set(id, {
      type: 'EdgeExpression',
      kind,
      inner,
      multiline: inner.includes('\n'),
    })
    out += `__EDGE_EXPR_${id}__`
    line = tok.loc.end.line
  }

  function emitComment(tok) {
    emitNewlinesTo(tok.loc.start.line)
    const id = nextId++
    const inner = tok.value
    sideTable.set(id, {
      type: 'EdgeComment',
      inner,
      multiline: inner.includes('\n'),
    })
    out += `__EDGE_EXPR_${id}__`
    line = tok.loc.end.line
  }

  function emitInlineTag(tok, kind) {
    emitNewlinesTo(tok.loc.start.line)
    const id = nextId++
    const argsRaw = restoreArgs(tok.properties.jsArg, tagArgs)
    const args = argsRaw && argsRaw.length > 0 ? argsRaw : null
    sideTable.set(id, {
      type: kind === 'void' ? 'EdgeVoid' : 'EdgeInline',
      name: tok.properties.name,
      args,
      swallow: false,
    })
    out += `<edge-self data-edge-id="${id}"></edge-self>`
    line = tok.loc.end.line
  }

  function emitBlockTag(tok) {
    emitNewlinesTo(tok.loc.start.line)
    const id = nextId++
    const node = { type: 'EdgeBlock', branches: [] }
    sideTable.set(id, node)

    const branches = [
      {
        name: tok.properties.name,
        args: restoreArgs(tok.properties.jsArg, tagArgs) || null,
        swallow: false,
        openerLine: tok.loc.start.line,
        bodyTokens: [],
      },
    ]
    for (const child of tok.children) {
      if (child.type === 'tag') {
        const head = child.properties.name.split('.')[0]
        if (BRANCH_TAGS.has(head)) {
          const restored = restoreArgs(child.properties.jsArg, tagArgs)
          branches.push({
            name: child.properties.name,
            args: restored && restored.length > 0 ? restored : null,
            swallow: false,
            openerLine: child.loc.start.line,
            bodyTokens: [],
          })
          continue
        }
      }
      branches[branches.length - 1].bodyTokens.push(child)
    }
    node.branches = branches.map(({ bodyTokens: _b, openerLine: _o, ...rest }) => ({
      ...rest,
      body: null,
    }))

    out += `<edge-block data-edge-id="${id}">`
    line = tok.loc.end.line

    for (let i = 0; i < branches.length; i++) {
      if (i > 0) {
        emitNewlinesTo(branches[i].openerLine)
        out += `<edge-branch data-edge-id="${id}" data-branch-index="${i}"></edge-branch>`
      }
      emitTokens(branches[i].bodyTokens)
    }
    out += `</edge-block>`
  }

  function emitTokens(toks) {
    for (const tok of toks) {
      if (tok.type === 'raw') {
        emitNewlinesTo(tok.line)
        out += tok.value
        // raw tokens don't move line forward — they're one line of content.
      } else if (tok.type === 'newline') {
        // The lexer's own newline tokens are unreliable; we drive newlines
        // from per-token .line / .loc instead.
      } else if (tok.type === 'comment') {
        emitComment(tok)
      } else if (
        tok.type === 'mustache' ||
        tok.type === 's__mustache' ||
        tok.type === 'e__mustache' ||
        tok.type === 'es__mustache'
      ) {
        emitMustache(tok)
      } else if (tok.type === 'tag') {
        const cls = classifyTag(tok)
        if (cls === 'block') emitBlockTag(tok)
        else if (cls === 'void') emitInlineTag(tok, 'void')
        else emitInlineTag(tok, 'inline')
      }
    }
  }

  emitTokens(tokens)
  return { masked: out, sideTable }
}
